# Values that can never hold a nested model, so they need no cycle bookkeeping.
_SCALARS = (str, bytes, bool, int, float)


def _as_mapping(value: object) -> Mapping[str, object]:
    if isinstance(value, Mapping):
        return value
    if is_dataclass(value) and not isinstance(value, type):
        return {field.name: getattr(value, field.name) for field in fields(value)}
    model_dump = getattr(value, "model_dump", None)
    if callable(model_dump):
        return model_dump(by_alias=True, exclude_unset=True)
    raise TypeError("model construction values must be mappings or model instances")


def _field_value(value: object, wire_name: str, python_name: str) -> tuple[bool, object]:
    mapping = _as_mapping(value)
    if python_name in mapping:
        return True, mapping[python_name]
    if wire_name in mapping:
        return True, mapping[wire_name]
    return False, None


def _property_name(wire_name: str, schema: Mapping[str, Any]) -> str:
    return str(schema.get("python", wire_name))


def _child_field(field: str, child: str) -> str:
    return f"{field}.{child}" if field else child


def _resolve(schema: Mapping[str, Any]) -> tuple[str | None, Mapping[str, Any]]:
    """Follows a reference chain to the named schema it points at."""
    name: str | None = None
    visited: set[str] = set()
    reference = schema.get("ref")
    while isinstance(reference, str) and reference not in visited:
        visited.add(reference)
        name = reference
        target = _SCHEMAS.get(reference)
        schema = target if isinstance(target, Mapping) else {}
        reference = schema.get("ref")
    return name, schema


def _holds(value: object, member: Mapping[str, Any]) -> bool:
    """Whether a union member's declared type can hold a container value at all."""
    declared = _resolve(member)[1].get("type")
    if isinstance(value, (list, tuple)):
        kind = "array"
    elif isinstance(value, Mapping) or is_dataclass(value) or hasattr(value, "model_dump"):
        kind = "object"
    else:
        return True
    return declared is None or kind in (declared if isinstance(declared, list) else [declared])


def _select_member(
    value: object,
    members: list[Any],
    field: str,
    active: set[tuple[int, int]],
) -> Mapping[str, Any] | None:
    """Returns the first union member the value satisfies, or raises its error."""
    rejection: SdkValidationError | None = None
    for member in members:
        if not isinstance(member, Mapping) or not _holds(value, member):
            continue
        try:
            _validate_node(value, member, field, active)
        except SdkValidationError as error:
            rejection = rejection or error
            continue
        return member
    if rejection is not None:
        raise rejection
    return None


def _validate_node(
    value: object,
    schema: Mapping[str, Any],
    field: str,
    active: set[tuple[int, int]],
) -> None:
    _name, resolved = _resolve(schema)
    if value is None:
        return

    # Recursive schemas describe finite values, so every node is validated. Only
    # a value that contains itself repeats a (value, schema) pair, and that can
    # never be constructed into a model.
    if not isinstance(value, _SCALARS):
        visit = (id(value), id(resolved))
        if visit in active:
            raise SdkValidationError(
                field,
                "recursion",
                f"Validation failed for '{field}': model value contains itself",
            )
        active = {*active, visit}

    for member in resolved.get("allOf", ()):
        if isinstance(member, Mapping):
            _validate_node(value, member, field, active)

    members = resolved.get("oneOf") or resolved.get("anyOf")
    if isinstance(members, list) and members:
        _select_member(value, members, field, active)
        return

    properties = resolved.get("properties")
    if isinstance(properties, Mapping):
        required = resolved.get("required", ())
        for wire_name in required if isinstance(required, list) else ():
            property_schema = properties.get(wire_name)
            python_name = (
                _property_name(wire_name, property_schema)
                if isinstance(property_schema, Mapping)
                else wire_name
            )
            present, property_value = _field_value(value, wire_name, python_name)
            if (
                not present
                or property_value is None
                and not (
                    isinstance(property_schema, Mapping) and property_schema.get("nullable") is True
                )
            ):
                raise SdkValidationError(
                    _child_field(field, wire_name),
                    "required",
                    f"Missing required property '{wire_name}'",
                )

        for wire_name, property_schema in properties.items():
            if not isinstance(property_schema, Mapping):
                continue
            present, property_value = _field_value(
                value, wire_name, _property_name(wire_name, property_schema)
            )
            if present:
                _validate_node(
                    property_value,
                    property_schema,
                    _child_field(field, wire_name),
                    active,
                )

    additional = resolved.get("additionalProperties")
    if isinstance(additional, Mapping) and isinstance(value, Mapping):
        known = {
            name
            for wire_name, property_schema in (properties or {}).items()
            if isinstance(property_schema, Mapping)
            for name in (wire_name, _property_name(wire_name, property_schema))
        }
        for key, property_value in value.items():
            if key not in known:
                _validate_node(property_value, additional, _child_field(field, key), active)

    items = resolved.get("items")
    if isinstance(value, (list, tuple)) and isinstance(items, Mapping):
        for index, item in enumerate(value):
            _validate_node(item, items, _child_field(field, str(index)), active)

    if any(
        resolved.get(key) is not None
        for key in ("minimum", "maximum", "exclusiveMinimum", "exclusiveMaximum", "multipleOf")
    ):
        validate_range(
            field,
            value,
            min=resolved.get("minimum"),
            max=resolved.get("maximum"),
            exclusive_min=resolved.get("exclusiveMinimum"),
            exclusive_max=resolved.get("exclusiveMaximum"),
            multiple_of=resolved.get("multipleOf"),
        )

    if any(resolved.get(key) is not None for key in ("minLength", "maxLength")):
        validate_length(
            field, cast(str, value), min=resolved.get("minLength"), max=resolved.get("maxLength")
        )

    if any(resolved.get(key) is not None for key in ("minItems", "maxItems")):
        validate_items(field, value, min=resolved.get("minItems"), max=resolved.get("maxItems"))

    if resolved.get("format") == "email":
        validate_email(field, cast(str, value))

    if resolved.get("format") == "date-time":
        validate_date_time(field, cast(str, value))

    if resolved.get("format") == "byte":
        validate_byte(field, cast(str, value))


def _build(type_name: str | None, values: dict[str, object]) -> object:
    model_type = _MODEL_TYPES.get(type_name) if type_name is not None else None
    if model_type is None or MODEL_CONSTRUCTION_STYLE == "typeddict":
        return values
    return model_type(**values)


def _hydrate(value: object, schema: Mapping[str, Any], field: str) -> object:
    """Builds the public value for one schema node, constructing nested models."""
    name, resolved = _resolve(schema)
    if value is None:
        return None

    members = resolved.get("oneOf") or resolved.get("anyOf")
    if isinstance(members, list) and members:
        member = _select_member(value, members, field, set())
        return value if member is None else _hydrate(value, member, field)

    properties = resolved.get("properties")
    if isinstance(properties, Mapping):
        values: dict[str, object] = {}
        for wire_name, property_schema in properties.items():
            if not isinstance(property_schema, Mapping):
                continue
            python_name = _property_name(wire_name, property_schema)
            present, property_value = _field_value(value, wire_name, python_name)
            if present:
                values[python_name] = _hydrate(
                    property_value, property_schema, _child_field(field, wire_name)
                )
        return _build(name, values)

    additional = resolved.get("additionalProperties")
    if isinstance(additional, Mapping) and isinstance(value, Mapping):
        return {
            key: _hydrate(item, additional, _child_field(field, key)) for key, item in value.items()
        }

    items = resolved.get("items")
    if isinstance(items, Mapping) and isinstance(value, (list, tuple)):
        return [
            _hydrate(item, items, _child_field(field, str(index)))
            for index, item in enumerate(value)
        ]

    return value


def _construct_model(value: object, type_name: str) -> object:
    if type_name not in _MODEL_TYPES:
        raise ValueError(f"unknown model type: {type_name}")
    _validate_node(value, {"ref": type_name}, "", set())
    if MODEL_CONSTRUCTION_STYLE == "pydantic":
        # Pydantic owns nested construction: its declared field types already
        # describe every referenced model. The wire remapper first restores the
        # spec spelling that the generated aliases and validators expect.
        return _MODEL_TYPES[type_name].model_validate(to_wire(value, type_name))
    return _hydrate(value, {"ref": type_name}, "")


